from pathlib import Path
p=Path('sethiportfolio-admin.html')
s=p.read_text(encoding='utf-8')

# Add management UI before admin-panel close.
needle='''            <section class="card mt-6 overflow-hidden">\n                <div class="p-5 border-b border-gray-100 flex items-center justify-between gap-4">\n                    <div><p class="text-[10px] font-black uppercase tracking-[0.14em] text-gray-400">Verification</p><h2 class="text-lg font-black mt-1">Recent Portfolio Transactions</h2></div>\n                    <a href="sethiportfolio.html" target="_blank" class="text-xs font-black text-blue-700 hover:text-blue-900">Open public portfolio →</a>\n                </div>\n                <div id="recent-transactions" class="divide-y divide-gray-100"><div class="p-6 text-sm text-gray-400">Loading transactions…</div></div>\n            </section>\n'''
replacement=needle+'''\n            <section class="card mt-6 overflow-hidden">\n                <div class="p-5 border-b border-gray-100 flex items-center justify-between gap-4">\n                    <div><p class="text-[10px] font-black uppercase tracking-[0.14em] text-gray-400">Editorial control</p><h2 class="text-lg font-black mt-1">Manage Journal Entries</h2><p class="text-xs text-gray-500 mt-1">Edit publication state, linked rationale and written analysis, or deliberately delete an entry.</p></div>\n                    <span id="journal-count" class="text-[10px] font-black uppercase tracking-wider text-gray-400">0 entries</span>\n                </div>\n                <div id="journal-manager" class="divide-y divide-gray-100"><div class="p-6 text-sm text-gray-400">Loading journal entries…</div></div>\n            </section>\n\n            <div id="correction-modal" class="hidden fixed inset-0 z-[80] bg-gray-950/45 backdrop-blur-sm p-4 items-center justify-center">\n                <div class="w-full max-w-lg rounded-2xl bg-white border border-gray-200 shadow-2xl overflow-hidden">\n                    <div class="p-5 border-b border-gray-100 flex items-start justify-between gap-4">\n                        <div><p class="text-[10px] font-black uppercase tracking-[0.14em] text-red-700">Audit-preserving correction</p><h2 id="correction-title" class="text-xl font-black mt-1">Correct Transaction</h2><p class="text-xs text-gray-500 mt-1">The original row stays untouched. A reversal and corrected replacement are added on its original trade date.</p></div>\n                        <button type="button" onclick="closeCorrectionModal()" class="text-xl leading-none text-gray-400 hover:text-gray-900">×</button>\n                    </div>\n                    <form id="correction-form" class="p-5 space-y-4">\n                        <div class="grid grid-cols-2 gap-4"><div><label class="label" for="correction-qty">Correct quantity</label><input id="correction-qty" type="number" min="0" step="0.000001" class="field" required></div><div><label class="label" for="correction-price">Correct price</label><input id="correction-price" type="number" min="0" step="0.0001" class="field" required></div></div>\n                        <div class="grid grid-cols-2 gap-4"><div><label class="label" for="correction-fees">Correct fees</label><input id="correction-fees" type="number" min="0" step="0.01" class="field" required></div><div><label class="label" for="correction-fx">FX to GBP</label><input id="correction-fx" type="number" min="0" step="0.000001" class="field" required></div></div>\n                        <div><label class="label" for="correction-reason">Correction reason</label><textarea id="correction-reason" rows="3" class="field resize-y" placeholder="Explain the clerical/data correction" required></textarea></div>\n                        <div class="rounded-xl bg-amber-50 border border-amber-200 p-3 text-[11px] leading-relaxed text-amber-800">This does not erase history. The ledger will contain the original event, an explicit reversal and the corrected replacement.</div>\n                        <div class="flex gap-3"><button type="button" onclick="closeCorrectionModal()" class="flex-1 rounded-xl border border-gray-200 px-4 py-3 text-sm font-black hover:bg-gray-50">Cancel</button><button id="correction-submit" type="submit" class="flex-1 rounded-xl bg-red-700 text-white px-4 py-3 text-sm font-black hover:bg-red-800">Record correction</button></div>\n                    </form>\n                </div>\n            </div>\n'''
if needle not in s: raise SystemExit('transactions section not found')
s=s.replace(needle,replacement,1)

# Add edit cancel control below journal submit.
needle='''                        <button id="journal-submit" type="submit" class="w-full rounded-xl bg-amber-600 text-white px-4 py-3 text-sm font-black hover:bg-amber-700 transition">Save journal entry</button>\n'''
replacement=needle+'''                        <button id="journal-cancel-edit" type="button" onclick="cancelJournalEdit()" class="hidden w-full rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm font-black text-gray-600 hover:bg-gray-50">Cancel edit</button>\n'''
s=s.replace(needle,replacement,1)

# State variables.
s=s.replace("    let liveTransactions = [];\n", "    let liveTransactions = [];\n    let liveJournal = [];\n    let editingJournalId = null;\n    let correctingTransactionId = null;\n",1)

# logout state.
s=s.replace("        liveTransactions = [];\n", "        liveTransactions = [];\n        liveJournal = [];\n        editingJournalId = null;\n        correctingTransactionId = null;\n",1)

# Refresh: fetch admin journal too.
old='''            const [portfolioResponse, txnResponse] = await Promise.all([\n                fetch(`${API}/${PORTFOLIO}`),\n                fetch(`${API}/${PORTFOLIO}/transactions`)\n            ]);\n            if (!portfolioResponse.ok || !txnResponse.ok) throw new Error('Unable to load current portfolio state.');\n            const portfolio = await portfolioResponse.json();\n            const txns = await txnResponse.json();\n'''
new='''            const [portfolioResponse, txnResponse, journalData] = await Promise.all([\n                fetch(`${API}/${PORTFOLIO}`),\n                fetch(`${API}/${PORTFOLIO}/transactions`),\n                apiFetch(`/admin/${PORTFOLIO}/journal`)\n            ]);\n            if (!portfolioResponse.ok || !txnResponse.ok) throw new Error('Unable to load current portfolio state.');\n            const portfolio = await portfolioResponse.json();\n            const txns = await txnResponse.json();\n'''
if old not in s: raise SystemExit('refresh fetch block missing')
s=s.replace(old,new,1)
s=s.replace("            liveTransactions = txns.transactions || [];\n", "            liveTransactions = txns.transactions || [];\n            liveJournal = journalData.journal || [];\n",1)
s=s.replace("            renderRecentTransactions();\n", "            renderRecentTransactions();\n            renderJournalManager();\n",1)

# Replace recent txn renderer with correction actions.
start=s.index('    function renderRecentTransactions() {')
end=s.index('\n    function updateTransactionPreview()', start)
newfunc='''    function renderRecentTransactions() {\n        const container = el('recent-transactions');\n        container.replaceChildren();\n        if (!liveTransactions.length) {\n            const empty = document.createElement('div'); empty.className='p-6 text-sm text-gray-400'; empty.textContent='No transactions recorded.'; container.appendChild(empty); return;\n        }\n        [...liveTransactions].reverse().slice(0,12).forEach(txn => {\n            const instrument = txn.instruments || {};\n            const isCorrection = /^(REVERSAL|CORRECTION) of /.test(txn.note || '');\n            const row = document.createElement('div'); row.className='p-4 md:px-5 flex flex-col sm:flex-row sm:items-center justify-between gap-3';\n            const left = document.createElement('div'); left.className='min-w-0';\n            const top = document.createElement('div'); top.className='flex items-center gap-2 flex-wrap';\n            const symbol = document.createElement('span'); symbol.className='text-sm font-black'; symbol.textContent=instrument.symbol || '—';\n            const side = document.createElement('span'); side.className=`text-[9px] font-black uppercase tracking-wider rounded-full px-2 py-0.5 ${String(txn.side).toUpperCase()==='BUY'?'bg-emerald-50 text-emerald-700':'bg-red-50 text-red-700'}`; side.textContent=txn.side;\n            top.append(symbol, side);\n            if (isCorrection) { const badge=document.createElement('span'); badge.className='text-[9px] font-black uppercase tracking-wider rounded-full px-2 py-0.5 bg-amber-50 text-amber-700'; badge.textContent=(txn.note||'').startsWith('REVERSAL')?'Reversal':'Corrected'; top.appendChild(badge); }\n            const detail = document.createElement('p'); detail.className='text-xs text-gray-500 mt-1 truncate'; detail.textContent=`${Number(txn.quantity || 0).toLocaleString('en-GB')} units @ ${money(txn.price, txn.currency || instrument.currency || 'GBP')}${txn.note ? ' · ' + txn.note : ''}`;\n            left.append(top, detail);\n            const actions=document.createElement('div'); actions.className='flex items-center gap-3 shrink-0';\n            const date = document.createElement('span'); date.className='text-xs font-bold text-gray-400'; date.textContent=prettyDate(txn.trade_date); actions.appendChild(date);\n            if (!isCorrection) { const btn=document.createElement('button'); btn.type='button'; btn.className='text-[11px] font-black text-red-700 hover:text-red-900'; btn.textContent='Correct trade'; btn.onclick=()=>openCorrectionModal(txn.id); actions.appendChild(btn); }\n            row.append(left,actions); container.appendChild(row);\n        });\n    }\n\n    function renderJournalManager() {\n        const container=el('journal-manager'); container.replaceChildren(); el('journal-count').textContent=`${liveJournal.length} ${liveJournal.length===1?'entry':'entries'}`;\n        if (!liveJournal.length) { const empty=document.createElement('div'); empty.className='p-6 text-sm text-gray-400'; empty.textContent='No journal entries recorded.'; container.appendChild(empty); return; }\n        liveJournal.forEach(entry=>{\n            const row=document.createElement('div'); row.className='p-4 md:px-5 flex flex-col sm:flex-row sm:items-center justify-between gap-3';\n            const left=document.createElement('div'); left.className='min-w-0';\n            const top=document.createElement('div'); top.className='flex items-center gap-2 flex-wrap';\n            const title=document.createElement('span'); title.className='text-sm font-black'; title.textContent=entry.title;\n            const state=document.createElement('span'); state.className=`text-[9px] font-black uppercase tracking-wider rounded-full px-2 py-0.5 ${entry.is_published?'bg-emerald-50 text-emerald-700':'bg-gray-100 text-gray-600'}`; state.textContent=entry.is_published?'Published':'Draft';\n            top.append(title,state);\n            const detail=document.createElement('p'); detail.className='text-xs text-gray-500 mt-1 truncate'; detail.textContent=`${entry.category} · Effective ${prettyDate(entry.effective_date)}${entry.related_transaction_id?' · Linked decision':''}`; left.append(top,detail);\n            const actions=document.createElement('div'); actions.className='flex gap-3 shrink-0';\n            const edit=document.createElement('button'); edit.type='button'; edit.className='text-[11px] font-black text-blue-700 hover:text-blue-900'; edit.textContent='Edit'; edit.onclick=()=>editJournalEntry(entry.id);\n            const del=document.createElement('button'); del.type='button'; del.className='text-[11px] font-black text-red-700 hover:text-red-900'; del.textContent='Delete'; del.onclick=()=>deleteJournalEntry(entry.id); actions.append(edit,del); row.append(left,actions); container.appendChild(row);\n        });\n    }\n\n    function editJournalEntry(id) {\n        const entry=liveJournal.find(x=>x.id===id); if(!entry) return; editingJournalId=id;\n        el('journal-category').value=entry.category; el('journal-date').value=entry.effective_date; el('journal-title').value=entry.title; el('journal-summary').value=entry.summary; el('journal-body').value=entry.body; el('journal-transaction').value=entry.related_transaction_id||''; el('journal-published').checked=!!entry.is_published;\n        el('journal-submit').textContent='Update journal entry'; el('journal-cancel-edit').classList.remove('hidden'); el('journal-title').scrollIntoView({behavior:'smooth',block:'center'});\n    }\n\n    function cancelJournalEdit() { editingJournalId=null; el('journal-form').reset(); el('journal-published').checked=true; el('journal-submit').textContent='Save journal entry'; el('journal-cancel-edit').classList.add('hidden'); setTodayDefaults(); renderTransactionOptions(); }\n\n    async function deleteJournalEntry(id) {\n        const entry=liveJournal.find(x=>x.id===id); if(!entry) return;\n        const typed=prompt(`Delete journal entry “${entry.title}”?\\n\\nType DELETE to confirm.`); if(typed!=='DELETE') return;\n        try { await apiFetch(`/admin/${PORTFOLIO}/journal/${id}`,{method:'DELETE'}); setMessage('global-message',`Deleted journal entry: ${entry.title}.`,'success'); if(editingJournalId===id) cancelJournalEdit(); await refreshAdminData(); } catch(error){ setMessage('global-message',error.message,'error'); }\n    }\n\n    function openCorrectionModal(id) {\n        const txn=liveTransactions.find(x=>x.id===id); if(!txn) return; correctingTransactionId=id; const instrument=txn.instruments||{}; el('correction-title').textContent=`Correct ${txn.side} ${instrument.symbol||''}`; el('correction-qty').value=txn.quantity; el('correction-price').value=txn.price; el('correction-fees').value=txn.fees||0; el('correction-fx').value=txn.fx_rate_to_base||1; el('correction-reason').value=''; const modal=el('correction-modal'); modal.classList.remove('hidden'); modal.classList.add('flex'); document.body.style.overflow='hidden';\n    }\n    function closeCorrectionModal(){ correctingTransactionId=null; const modal=el('correction-modal'); modal.classList.add('hidden'); modal.classList.remove('flex'); document.body.style.overflow=''; }\n\n    el('correction-form').addEventListener('submit',async event=>{\n        event.preventDefault(); if(!correctingTransactionId) return; const payload={quantity:Number(el('correction-qty').value),price:Number(el('correction-price').value),fees:Number(el('correction-fees').value||0),fx_rate_to_base:Number(el('correction-fx').value||1),reason:el('correction-reason').value.trim()};\n        if(!confirm('Record an audit-preserving reversal and replacement for this transaction?')) return; const btn=el('correction-submit'); btn.disabled=true; btn.textContent='Recording…';\n        try { await apiFetch(`/admin/${PORTFOLIO}/transaction/${correctingTransactionId}/correct`,{method:'POST',body:JSON.stringify(payload)}); closeCorrectionModal(); setMessage('global-message','Transaction correction recorded as reversal + corrected replacement.','success'); await refreshAdminData(); } catch(error){ setMessage('global-message',error.message,'error'); } finally { btn.disabled=false; btn.textContent='Record correction'; }\n    });\n    el('correction-modal').addEventListener('click',event=>{if(event.target===el('correction-modal')) closeCorrectionModal();});\n    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!el('correction-modal').classList.contains('hidden')) closeCorrectionModal();});\n'''
s=s[:start]+newfunc+s[end:]

# Journal submit create/update.
old="""            await apiFetch(`/admin/${PORTFOLIO}/journal`, { method:'POST', body:JSON.stringify(payload) });\n            setMessage('global-message', payload.is_published ? 'Journal entry published successfully.' : 'Journal entry saved as unpublished.', 'success');\n            el('journal-form').reset(); el('journal-published').checked=true; setTodayDefaults(); renderTransactionOptions();\n"""
new="""            const path = editingJournalId ? `/admin/${PORTFOLIO}/journal/${editingJournalId}` : `/admin/${PORTFOLIO}/journal`;\n            const method = editingJournalId ? 'PATCH' : 'POST';\n            await apiFetch(path, { method, body:JSON.stringify(payload) });\n            setMessage('global-message', editingJournalId ? 'Journal entry updated successfully.' : (payload.is_published ? 'Journal entry published successfully.' : 'Journal entry saved as unpublished.'), 'success');\n            editingJournalId=null; el('journal-form').reset(); el('journal-published').checked=true; el('journal-submit').textContent='Save journal entry'; el('journal-cancel-edit').classList.add('hidden'); setTodayDefaults(); renderTransactionOptions(); await refreshAdminData();\n"""
if old not in s: raise SystemExit('journal submit block missing')
s=s.replace(old,new,1)
# preserve correct button text after submission finally
s=s.replace("finally { btn.disabled=false; btn.textContent='Save journal entry'; }", "finally { btn.disabled=false; btn.textContent=editingJournalId ? 'Update journal entry' : 'Save journal entry'; }",1)

p.write_text(s,encoding='utf-8')
print('Phase 2E frontend patched')
